import sqlparse, sys, traceback
# find threshold where parse OK but str() raw-RecursionErrors
import sqlparse.sql as S
def mk(N): return "SELECT * FROM " + "(SELECT * FROM " * N + "t" + ")" * N
# lower recursion limit to make it fast
for lim in (200, 300, 500):
    sys.setrecursionlimit(lim)
    for N in (20, 40, 60, 80, 120, 200):
        s = mk(N)
        try:
            st = sqlparse.parse(s)[0]
        except Exception as e:
            print(f"lim={lim} N={N}: parse -> {type(e).__name__}: {e}")
            continue
        # now operations OUTSIDE the FilterStack guard
        for op, fn in (("str", lambda st=st: str(st)),
                       ("flatten", lambda st=st: list(st.flatten())),
                       ("pprint", lambda st=st: st._pprint_tree(f=open('/dev/null','w'))),
                       ("repr", lambda st=st: repr(st))):
            try:
                fn()
            except RecursionError as e:
                print(f"lim={lim} N={N}: {op} -> RAW RecursionError")
            except Exception as e:
                print(f"lim={lim} N={N}: {op} -> {type(e).__name__}: {e}")
sys.setrecursionlimit(1000)
EOF
