import sqlparse
b = "select 'café' from t".encode('latin-1')
print("raw bytes:", b)
for kw in ({}, {'encoding':'latin-1'}, {'encoding':'utf-8'}, {'encoding':'cp1252'}):
    try:
        print(f"format(bytes, {kw}) ->", repr(sqlparse.format(b, reindent=True, **kw)))
    except Exception as e:
        print(f"format(bytes, {kw}) RAISED {type(e).__name__}: {e}")
# genuinely invalid utf-8 that is also invalid unicode-escape
for bad in (b"select \xff\xfe from t", b"select '\\u' from t", b"select '\\x' from t", b"\\N{NOPE}"):
    try:
        print(f"format({bad!r}) ->", repr(sqlparse.format(bad)))
    except Exception as e:
        print(f"format({bad!r}) RAISED {type(e).__name__}: {e}")
# surrogates
try:
    print("format surrogate:", repr(sqlparse.format('select \ud800 from t')))
except Exception as e:
    print("format surrogate RAISED", type(e).__name__, e)
EOF
